import json
data = json.load(open('/app/resources/treasury_bulletin_2011_09.json'))

# Let's look at the structure of the JSON more carefully
# Look for any tables with USCC data
def find_elements(d, target_str='', depth=0):
    if depth > 5:
        return
    if isinstance(d, dict):
        for k, v in d.items():
            if isinstance(v, (dict, list)):
                find_elements(v, target_str, depth+1)
            elif isinstance(v, str) and target_str in v:
                print(f"Found at depth {depth}, key {k}: {v[:100]}")
    elif isinstance(d, list):
        for item in d[:5]:  # Only check first few
            find_elements(item, target_str, depth+1)

# Let's specifically look at what the 'pages' contain
print("Checking pages structure...")
if 'document' in data and 'pages' in data['document']:
    for i, page in enumerate(data['document']['pages'][:3]):
        print(f"\n--- Page {i} ---")
        if 'elements' in page:
            print(f"  Number of elements: {len(page['elements'])}")
            for j, elem in enumerate(page['elements'][:5]):
                print(f"  Element {j}: {list(elem.keys())}")
                if 'description' in elem:
                    print(f"    Desc: {elem['description'][:80]}")
                if 'content' in elem and elem['content']:
                    print(f"    Content type: {type(elem['content'])}")
EOF
